//! Stubbed kernel environment for the Rust sources generated by the Zither `kernel` backend
//! (`syscall_sigs.rs`, `syscall_numbers.rs`, and `kernel_wrappers.rs`).
//!
//! The goldens are compiled and clippy-checked against minimal stubs of the kernel modules they
//! reference. The stubs are instrumented (see [`instrumentation`]) so that the unit tests below
//! can call the generated `wrapper_<syscall>` entry points and observe how they sanitize their
//! arguments, forward to `sys_<syscall>`, copy output handles back to user memory and signal
//! policy exceptions.

use zx_status::Status;
use zx_types::ZX_OK;

#[path = "goldens/kernel/syscall_sigs.rs"]
pub mod syscall_sigs;

/// Instrumentation shared by the kernel stubs: a per-thread log of what the generated wrappers
/// asked the kernel to do, and the user addresses whose copy-out should fail.
pub mod instrumentation {
    use std::cell::RefCell;
    use zx_status::Status;

    /// An interaction between a generated wrapper and the stubbed kernel.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub enum Event {
        /// `do_syscall` was entered with the given syscall number and user program counter.
        DoSyscall {
            /// The `ZX_SYS_*` syscall number.
            syscall_num: u64,
            /// The user program counter.
            pc: u64,
        },
        /// `ValidSyscallPC::<syscall>` was consulted to validate the user program counter.
        ValidSyscallPC(&'static str),
        /// `sys_<syscall>` was called with the given sanitized arguments.
        SysCall {
            /// The syscall name.
            name: &'static str,
            /// The arguments as raw 64-bit values: integers widened, handles as their raw values
            /// and user pointers as their addresses.
            args: Vec<u64>,
        },
        /// `UserOutPtr::copy_to_user` was asked to copy a value to a user address.
        CopyToUser {
            /// The user address.
            addr: usize,
            /// The value, widened to 64 bits.
            value: u64,
        },
        /// `thread::signal_policy_exception` was called.
        SignalPolicyException {
            /// The `ZX_EXCP_POLICY_CODE_*` code.
            code: u32,
            /// The code-specific data.
            data: u32,
        },
    }

    thread_local! {
        static EVENTS: RefCell<Vec<Event>> = const { RefCell::new(Vec::new()) };
        static FAULTING_USER_ADDRS: RefCell<Vec<usize>> = const { RefCell::new(Vec::new()) };
    }

    /// Records `event` in the current thread's log.
    pub fn record(event: Event) {
        EVENTS.with_borrow_mut(|events| events.push(event));
    }

    /// Returns the events recorded on the current thread so far and clears the log.
    pub fn take_events() -> Vec<Event> {
        EVENTS.with_borrow_mut(std::mem::take)
    }

    /// Makes every subsequent user copy to `addr` on the current thread fail with
    /// `Status::INVALID_ARGS`, as a copy to an unmapped user address would.
    pub fn fault_user_addr(addr: usize) {
        FAULTING_USER_ADDRS.with_borrow_mut(|addrs| addrs.push(addr));
    }

    /// Returns the result of a user copy to `addr` on the current thread.
    pub fn user_copy_result(addr: usize) -> Result<(), Status> {
        if FAULTING_USER_ADDRS.with_borrow(|addrs| addrs.contains(&addr)) {
            Err(Status::INVALID_ARGS)
        } else {
            Ok(())
        }
    }

    /// Clears the current thread's event log and faulting user addresses.
    pub fn reset() {
        EVENTS.with_borrow_mut(Vec::clear);
        FAULTING_USER_ADDRS.with_borrow_mut(Vec::clear);
    }
}

#[macro_export]
#[doc(hidden)]
macro_rules! __zither_test_resolve_string {
    ($string:literal) => {{
        static STRING: crate::ktrace_rs::InternedString = crate::ktrace_rs::InternedString($string);
        &STRING
    }};
}

/// Minimal stub of `crate::ktrace_rs`.
pub mod ktrace_rs {
    /// Interned string reference used in `SYSCALL_NAME_REFS`.
    pub struct InternedString(pub &'static str);

    #[doc(hidden)]
    pub use crate::__zither_test_resolve_string as resolve_string;
}

/// Minimal stub of `crate::kernel`.
pub mod kernel {
    /// Minimal stub of `crate::kernel::thread`.
    pub mod thread {
        use crate::instrumentation::{self, Event};

        /// Signals a policy exception on the current thread.
        pub fn signal_policy_exception(code: u32, data: u32) {
            instrumentation::record(Event::SignalPolicyException { code, data });
        }
    }
}

/// Minimal stub of `crate::object`.
pub mod object {
    use zx_types::zx_handle_t;

    /// Wrapper around a raw `zx_handle_t` received from userspace.
    #[repr(transparent)]
    #[derive(Copy, Clone)]
    pub struct HandleValue(pub zx_handle_t);

    impl HandleValue {
        /// Constructs a `HandleValue` from a raw handle.
        pub const fn new(value: zx_handle_t) -> Self {
            Self(value)
        }

        /// Returns the raw `zx_handle_t` value.
        pub const fn raw_value(&self) -> zx_handle_t {
            self.0
        }
    }
}

/// Minimal stub of `crate::user_copy`.
pub mod user_copy {
    use crate::instrumentation::{self, Event};
    use zx_status::Status;

    /// Read-only user pointer wrapper.
    #[repr(transparent)]
    #[derive(Copy, Clone)]
    pub struct UserInPtr<T>(pub *const T);

    /// Write-only user pointer wrapper.
    #[repr(transparent)]
    #[derive(Copy, Clone)]
    pub struct UserOutPtr<T>(pub *mut T);

    /// Read-write user pointer wrapper.
    #[repr(transparent)]
    #[derive(Copy, Clone)]
    pub struct UserInOutPtr<T>(pub *mut T);

    impl<T: Copy + Into<u64>> UserOutPtr<T> {
        /// Copies a single value to user memory.
        pub fn copy_to_user(&self, src: &T) -> Result<(), Status> {
            let addr = self.0.addr();
            instrumentation::record(Event::CopyToUser { addr, value: (*src).into() });
            instrumentation::user_copy_result(addr)
        }
    }
}

/// Minimal stub of `crate::syscalls_rs`.
#[path = "goldens"]
pub mod syscalls_rs {
    use super::{Status, ZX_OK};
    use crate::instrumentation::{self, Event};

    #[path = "kernel/syscall_numbers.rs"]
    pub mod syscall_numbers;

    #[path = "kernel/kernel_wrappers.rs"]
    pub mod kernel_wrappers;

    /// Minimal stub of `crate::syscalls_rs::safe_syscall_argument`.
    pub mod safe_syscall_argument {
        use super::{UserInOutPtr, UserInPtr, UserOutPtr};
        use crate::object::HandleValue;
        use zx_types::zx_handle_t;

        /// Trait for sanitizing raw 64-bit syscall register arguments.
        pub trait SafeSyscallArgument {
            /// Sanitizes a raw register value into `Self`.
            fn sanitize(value: u64) -> Self;
        }

        impl SafeSyscallArgument for u32 {
            fn sanitize(value: u64) -> Self {
                value as Self
            }
        }

        impl SafeSyscallArgument for i64 {
            fn sanitize(value: u64) -> Self {
                value as Self
            }
        }

        impl SafeSyscallArgument for usize {
            fn sanitize(value: u64) -> Self {
                value as Self
            }
        }

        impl SafeSyscallArgument for HandleValue {
            fn sanitize(value: u64) -> Self {
                HandleValue::new(zx_handle_t::sanitize(value))
            }
        }

        impl<T> SafeSyscallArgument for UserInPtr<T> {
            fn sanitize(value: u64) -> Self {
                Self(core::ptr::with_exposed_provenance(value as usize))
            }
        }

        impl<T> SafeSyscallArgument for UserOutPtr<T> {
            fn sanitize(value: u64) -> Self {
                Self(core::ptr::with_exposed_provenance_mut(value as usize))
            }
        }

        impl<T> SafeSyscallArgument for UserInOutPtr<T> {
            fn sanitize(value: u64) -> Self {
                Self(core::ptr::with_exposed_provenance_mut(value as usize))
            }
        }
    }

    use crate::user_copy::{UserInOutPtr, UserInPtr, UserOutPtr};

    /// Result returned from a syscall wrapper to the assembly entry point.
    #[repr(C)]
    pub struct SyscallResult {
        /// Syscall return status.
        pub status: u64,
        /// Non-zero if the thread was signaled.
        pub is_signaled: u64,
    }

    /// Conversion into the raw 64-bit value returned to user mode.
    pub trait SyscallReturn {
        /// Converts `self` into a raw 64-bit return register value.
        fn into_raw_return(self) -> u64;
    }

    impl SyscallReturn for Status {
        fn into_raw_return(self) -> u64 {
            i64::from(self.into_raw()) as u64
        }
    }

    impl SyscallReturn for Result<(), Status> {
        fn into_raw_return(self) -> u64 {
            match self {
                Ok(()) => i64::from(ZX_OK) as u64,
                Err(status) => status.into_raw_return(),
            }
        }
    }

    impl SyscallReturn for i64 {
        fn into_raw_return(self) -> u64 {
            self as u64
        }
    }

    /// Records that `ValidSyscallPC::<name>` was consulted; the stubbed vDSO accepts any PC.
    fn valid_syscall_pc(name: &'static str, _offset: usize) -> bool {
        instrumentation::record(Event::ValidSyscallPC(name));
        true
    }

    /// Validated vDSO syscall entry-point check functions.
    pub struct ValidSyscallPC;

    impl ValidSyscallPC {
        /// Returns whether `offset` is valid for `zx_channel_create`.
        pub fn channel_create(offset: usize) -> bool {
            valid_syscall_pc("channel_create", offset)
        }

        /// Returns whether `offset` is valid for `zx_channel_read`.
        pub fn channel_read(offset: usize) -> bool {
            valid_syscall_pc("channel_read", offset)
        }

        /// Returns whether `offset` is valid for `zx_channel_write`.
        pub fn channel_write(offset: usize) -> bool {
            valid_syscall_pc("channel_write", offset)
        }

        /// Returns whether `offset` is valid for `zx_clock_get_monotonic_via_kernel`.
        pub fn clock_get_monotonic_via_kernel(offset: usize) -> bool {
            valid_syscall_pc("clock_get_monotonic_via_kernel", offset)
        }

        /// Returns whether `offset` is valid for `zx_handle_close_many`.
        pub fn handle_close_many(offset: usize) -> bool {
            valid_syscall_pc("handle_close_many", offset)
        }

        /// Returns whether `offset` is valid for `zx_ktrace_control`.
        pub fn ktrace_control(offset: usize) -> bool {
            valid_syscall_pc("ktrace_control", offset)
        }

        /// Returns whether `offset` is valid for `zx_nanosleep`.
        pub fn nanosleep(offset: usize) -> bool {
            valid_syscall_pc("nanosleep", offset)
        }

        /// Returns whether `offset` is valid for `zx_process_exit`.
        pub fn process_exit(offset: usize) -> bool {
            valid_syscall_pc("process_exit", offset)
        }

        /// Returns whether `offset` is valid for `zx_syscall_next`.
        pub fn syscall_next(offset: usize) -> bool {
            valid_syscall_pc("syscall_next", offset)
        }

        /// Returns whether `offset` is valid for `zx_syscall_test0`.
        pub fn syscall_test0(offset: usize) -> bool {
            valid_syscall_pc("syscall_test0", offset)
        }

        /// Returns whether `offset` is valid for `zx_syscall_test1`.
        pub fn syscall_test1(offset: usize) -> bool {
            valid_syscall_pc("syscall_test1", offset)
        }

        /// Returns whether `offset` is valid for `zx_syscall_test2`.
        pub fn syscall_test2(offset: usize) -> bool {
            valid_syscall_pc("syscall_test2", offset)
        }
    }

    /// Executes a syscall with standard preamble and postamble checks.
    ///
    /// # Safety
    ///
    /// Must only be called on the syscall path of the current user thread with interrupts disabled.
    pub unsafe fn do_syscall<F: FnOnce() -> u64>(
        syscall_num: u64,
        pc: u64,
        valid_pc: fn(usize) -> bool,
        make_call: F,
    ) -> SyscallResult {
        instrumentation::record(Event::DoSyscall { syscall_num, pc });
        // The stubbed vDSO is loaded at address zero, so `pc` is also its offset into the vDSO.
        let status =
            if valid_pc(pc as usize) { make_call() } else { Status::BAD_SYSCALL.into_raw_return() };
        SyscallResult { status, is_signaled: 0 }
    }
}

#[cfg(test)]
mod tests {
    use super::instrumentation::{self, Event};
    use super::object::HandleValue;
    use super::syscall_sigs;
    use super::syscalls_rs::kernel_wrappers::*;
    use super::syscalls_rs::syscall_numbers::*;
    use super::user_copy::{UserInOutPtr, UserInPtr, UserOutPtr};
    use std::cell::Cell;
    use zx_status::Status;
    use zx_types::*;

    /// Garbage in the upper half of a register argument, which sanitization must discard for
    /// 32-bit parameters.
    const HIGH_GARBAGE: u64 = 0xdead_beef_0000_0000;

    /// The user program counter that issued the syscall.
    const PC: u64 = 0x7fff_0000_1234;

    /// The handles created by `sys_channel_create`.
    const CREATED_HANDLES: [zx_handle_t; 2] = [0x1000_0001, 0x1000_0002];

    /// User addresses of the `out0` and `out1` output handles of `zx_channel_create`.
    const OUT0_ADDR: u64 = 0x2000;
    const OUT1_ADDR: u64 = 0x3000;

    thread_local! {
        /// The result returned by the status-returning `sys_<syscall>` stubs.
        static SYS_STATUS: Cell<Result<(), Status>> = const { Cell::new(Ok(())) };
        /// The time returned by `sys_clock_get_monotonic_via_kernel`.
        static SYS_TIME: Cell<zx_time_t> = const { Cell::new(0) };
    }

    /// Resets the stubbed kernel to its initial state.
    fn reset() {
        instrumentation::reset();
        SYS_STATUS.set(Ok(()));
        SYS_TIME.set(0);
    }

    /// The raw 64-bit return register value of `status`.
    fn raw_return(status: Status) -> u64 {
        i64::from(status.into_raw()) as u64
    }

    /// The raw 64-bit return register value of `ZX_OK`.
    fn raw_return_ok() -> u64 {
        i64::from(ZX_OK) as u64
    }

    /// Conversion of a sanitized syscall argument into the raw value recorded in
    /// `Event::SysCall`.
    trait RawArg {
        fn raw_arg(self) -> u64;
    }

    impl RawArg for u32 {
        fn raw_arg(self) -> u64 {
            self.into()
        }
    }

    impl RawArg for i64 {
        fn raw_arg(self) -> u64 {
            self as u64
        }
    }

    impl RawArg for usize {
        fn raw_arg(self) -> u64 {
            self as u64
        }
    }

    impl RawArg for HandleValue {
        fn raw_arg(self) -> u64 {
            self.raw_value().into()
        }
    }

    impl<T> RawArg for UserInPtr<T> {
        fn raw_arg(self) -> u64 {
            self.0.addr() as u64
        }
    }

    impl<T> RawArg for UserOutPtr<T> {
        fn raw_arg(self) -> u64 {
            self.0.addr() as u64
        }
    }

    impl<T> RawArg for UserInOutPtr<T> {
        fn raw_arg(self) -> u64 {
            self.0.addr() as u64
        }
    }

    /// Records a `sys_<syscall>` call and its arguments.
    macro_rules! record_sys_call {
        ($name:literal $(, $arg:expr)* $(,)?) => {
            instrumentation::record(Event::SysCall {
                name: $name,
                args: vec![$($arg.raw_arg()),*],
            })
        };
    }

    //
    // The `sys_<syscall>` implementations that the generated wrappers link against. Each records
    // the (sanitized) arguments it received. Their signatures are checked against the generated
    // `syscall_sigs.rs` below.
    //

    #[unsafe(no_mangle)]
    #[allow(improper_ctypes_definitions)]
    extern "C" fn sys_channel_create(
        options: u32,
        out0: &mut HandleValue,
        out1: &mut HandleValue,
    ) -> Result<(), Status> {
        // The output handles are recorded as received, so that the tests can check that the
        // wrapper initialized them to `ZX_HANDLE_INVALID`.
        record_sys_call!("channel_create", options, out0.raw_value(), out1.raw_value());
        SYS_STATUS.get()?;
        *out0 = HandleValue::new(CREATED_HANDLES[0]);
        *out1 = HandleValue::new(CREATED_HANDLES[1]);
        Ok(())
    }

    #[unsafe(no_mangle)]
    #[allow(improper_ctypes_definitions)]
    extern "C" fn sys_channel_read(
        handle: HandleValue,
        options: u32,
        bytes: UserOutPtr<u8>,
        handles: UserOutPtr<zx_handle_t>,
        num_bytes: u32,
        num_handles: u32,
        actual_bytes: UserOutPtr<u32>,
        actual_handles: UserOutPtr<u32>,
    ) -> Result<(), Status> {
        record_sys_call!(
            "channel_read",
            handle,
            options,
            bytes,
            handles,
            num_bytes,
            num_handles,
            actual_bytes,
            actual_handles,
        );
        SYS_STATUS.get()
    }

    #[unsafe(no_mangle)]
    #[allow(improper_ctypes_definitions)]
    extern "C" fn sys_channel_write(
        handle: HandleValue,
        options: u32,
        bytes: UserInPtr<u8>,
        num_bytes: u32,
        handles: UserInPtr<zx_handle_t>,
        num_handles: u32,
    ) -> Result<(), Status> {
        record_sys_call!("channel_write", handle, options, bytes, num_bytes, handles, num_handles);
        SYS_STATUS.get()
    }

    #[unsafe(no_mangle)]
    extern "C" fn sys_clock_get_monotonic_via_kernel() -> zx_time_t {
        record_sys_call!("clock_get_monotonic_via_kernel");
        SYS_TIME.get()
    }

    #[unsafe(no_mangle)]
    #[allow(improper_ctypes_definitions)]
    extern "C" fn sys_handle_close_many(
        handles: UserInPtr<zx_handle_t>,
        num_handles: usize,
    ) -> Result<(), Status> {
        record_sys_call!("handle_close_many", handles, num_handles);
        SYS_STATUS.get()
    }

    #[unsafe(no_mangle)]
    #[allow(improper_ctypes_definitions)]
    extern "C" fn sys_ktrace_control(
        handle: HandleValue,
        action: u32,
        options: u32,
        ptr: UserInOutPtr<u8>,
    ) -> Result<(), Status> {
        record_sys_call!("ktrace_control", handle, action, options, ptr);
        SYS_STATUS.get()
    }

    #[unsafe(no_mangle)]
    #[allow(improper_ctypes_definitions)]
    extern "C" fn sys_nanosleep(deadline: zx_time_t) -> Result<(), Status> {
        record_sys_call!("nanosleep", deadline);
        SYS_STATUS.get()
    }

    /// Unlike the kernel's, this `sys_process_exit` returns, so that the tests can observe what
    /// the wrapper does if the implementation of a `noreturn` syscall were to return.
    #[unsafe(no_mangle)]
    extern "C" fn sys_process_exit(retcode: i64) {
        record_sys_call!("process_exit", retcode);
    }

    #[unsafe(no_mangle)]
    extern "C" fn sys_syscall_next() {
        record_sys_call!("syscall_next");
    }

    #[unsafe(no_mangle)]
    extern "C" fn sys_syscall_test0() {
        record_sys_call!("syscall_test0");
    }

    #[unsafe(no_mangle)]
    extern "C" fn sys_syscall_test1() {
        record_sys_call!("syscall_test1");
    }

    #[unsafe(no_mangle)]
    extern "C" fn sys_syscall_test2() {
        record_sys_call!("syscall_test2");
    }

    /// The `sys_<syscall>` stubs have the signatures generated in `syscall_sigs.rs`.
    const _: syscall_sigs::channel_create = sys_channel_create;
    const _: syscall_sigs::channel_read = sys_channel_read;
    const _: syscall_sigs::channel_write = sys_channel_write;
    const _: syscall_sigs::clock_get_monotonic_via_kernel = sys_clock_get_monotonic_via_kernel;
    const _: syscall_sigs::handle_close_many = sys_handle_close_many;
    const _: syscall_sigs::ktrace_control = sys_ktrace_control;
    const _: syscall_sigs::nanosleep = sys_nanosleep;
    const _: syscall_sigs::process_exit = sys_process_exit;
    const _: syscall_sigs::syscall_next = sys_syscall_next;
    const _: syscall_sigs::syscall_test0 = sys_syscall_test0;
    const _: syscall_sigs::syscall_test1 = sys_syscall_test1;
    const _: syscall_sigs::syscall_test2 = sys_syscall_test2;

    #[test]
    fn syscall_numbers_are_dense_and_index_the_syscall_names() {
        /// Every kernel syscall of the fixture, in syscall number order.
        const SYSCALLS: [(u64, &str); 12] = [
            (ZX_SYS_CHANNEL_CREATE, "channel_create"),
            (ZX_SYS_CHANNEL_READ, "channel_read"),
            (ZX_SYS_CHANNEL_WRITE, "channel_write"),
            (ZX_SYS_CLOCK_GET_MONOTONIC_VIA_KERNEL, "clock_get_monotonic_via_kernel"),
            (ZX_SYS_HANDLE_CLOSE_MANY, "handle_close_many"),
            (ZX_SYS_KTRACE_CONTROL, "ktrace_control"),
            (ZX_SYS_NANOSLEEP, "nanosleep"),
            (ZX_SYS_PROCESS_EXIT, "process_exit"),
            (ZX_SYS_SYSCALL_NEXT, "syscall_next"),
            (ZX_SYS_SYSCALL_TEST0, "syscall_test0"),
            (ZX_SYS_SYSCALL_TEST1, "syscall_test1"),
            (ZX_SYS_SYSCALL_TEST2, "syscall_test2"),
        ];
        assert_eq!(SYSCALLS.len(), ZX_SYS_COUNT, "update SYSCALLS for the new fixture syscalls");
        assert_eq!(SYSCALL_NAME_REFS.len(), ZX_SYS_COUNT);
        for (expected_num, (num, name)) in SYSCALLS.into_iter().enumerate() {
            assert_eq!(num, expected_num as u64, "{name}");
            assert_eq!(SYSCALL_NAME_REFS[num as usize].0, name);
        }
    }

    #[test]
    fn wrapper_sanitizes_and_forwards_arguments() {
        reset();
        // SAFETY: The stubbed `do_syscall` has no execution context requirements.
        let result = unsafe {
            wrapper_channel_read(
                HIGH_GARBAGE | 0x1234_5678,
                HIGH_GARBAGE | 0x3,
                0x1000,
                0x2000,
                HIGH_GARBAGE | 16,
                HIGH_GARBAGE | 2,
                0x3000,
                0x4000,
                PC,
            )
        };
        assert_eq!(result.status, raw_return_ok());
        assert_eq!(result.is_signaled, 0);
        assert_eq!(
            instrumentation::take_events(),
            [
                Event::DoSyscall { syscall_num: ZX_SYS_CHANNEL_READ, pc: PC },
                Event::ValidSyscallPC("channel_read"),
                Event::SysCall {
                    name: "channel_read",
                    args: vec![0x1234_5678, 0x3, 0x1000, 0x2000, 16, 2, 0x3000, 0x4000],
                },
            ]
        );
    }

    #[test]
    fn wrapper_forwards_pointer_and_wide_integer_arguments() {
        reset();
        // SAFETY: The stubbed `do_syscall` has no execution context requirements.
        let result = unsafe {
            wrapper_channel_write(0x1, HIGH_GARBAGE, 0x1000, HIGH_GARBAGE | 8, 0x2000, 0, PC)
        };
        assert_eq!(result.status, raw_return_ok());
        // SAFETY: As above.
        let result = unsafe { wrapper_ktrace_control(0x2, 1, HIGH_GARBAGE | 2, 0x3000, PC) };
        assert_eq!(result.status, raw_return_ok());
        // SAFETY: As above.
        let result = unsafe { wrapper_handle_close_many(0x4000, HIGH_GARBAGE | 3, PC) };
        assert_eq!(result.status, raw_return_ok());
        // SAFETY: As above.
        let result = unsafe { wrapper_nanosleep(u64::MAX, PC) };
        assert_eq!(result.status, raw_return_ok());
        let sys_calls: Vec<Event> = instrumentation::take_events()
            .into_iter()
            .filter(|event| matches!(event, Event::SysCall { .. }))
            .collect();
        assert_eq!(
            sys_calls,
            [
                Event::SysCall { name: "channel_write", args: vec![0x1, 0, 0x1000, 8, 0x2000, 0] },
                Event::SysCall { name: "ktrace_control", args: vec![0x2, 1, 2, 0x3000] },
                // `num_handles` is a `usize`, so its upper half is preserved.
                Event::SysCall { name: "handle_close_many", args: vec![0x4000, HIGH_GARBAGE | 3] },
                // The deadline is a `zx_time_t`, so all 64 bits are preserved.
                Event::SysCall { name: "nanosleep", args: vec![u64::MAX] },
            ]
        );
    }

    #[test]
    fn wrapper_returns_the_syscall_status() {
        reset();
        SYS_STATUS.set(Err(Status::TIMED_OUT));
        // SAFETY: The stubbed `do_syscall` has no execution context requirements.
        let result = unsafe { wrapper_nanosleep(0, PC) };
        assert_eq!(result.status, raw_return(Status::TIMED_OUT));
        assert_eq!(result.is_signaled, 0);
    }

    #[test]
    fn wrapper_returns_the_raw_value_of_a_non_status_syscall() {
        reset();
        for time in [0, 0x1_2345_6789, -5] {
            SYS_TIME.set(time);
            // SAFETY: The stubbed `do_syscall` has no execution context requirements.
            let result = unsafe { wrapper_clock_get_monotonic_via_kernel(PC) };
            assert_eq!(result.status, time as u64);
            assert_eq!(
                instrumentation::take_events(),
                [
                    Event::DoSyscall { syscall_num: ZX_SYS_CLOCK_GET_MONOTONIC_VIA_KERNEL, pc: PC },
                    Event::ValidSyscallPC("clock_get_monotonic_via_kernel"),
                    Event::SysCall { name: "clock_get_monotonic_via_kernel", args: vec![] },
                ]
            );
        }
    }

    #[test]
    fn wrapper_of_void_syscall_returns_ok() {
        reset();
        // SAFETY: The stubbed `do_syscall` has no execution context requirements.
        let result = unsafe { wrapper_syscall_test0(PC) };
        assert_eq!(result.status, raw_return_ok());
        assert_eq!(
            instrumentation::take_events(),
            [
                Event::DoSyscall { syscall_num: ZX_SYS_SYSCALL_TEST0, pc: PC },
                Event::ValidSyscallPC("syscall_test0"),
                Event::SysCall { name: "syscall_test0", args: vec![] },
            ]
        );
    }

    #[test]
    fn wrapper_of_noreturn_syscall_returns_bad_state_if_reached() {
        reset();
        // SAFETY: The stubbed `do_syscall` has no execution context requirements.
        let result = unsafe { wrapper_process_exit(HIGH_GARBAGE | 7, PC) };
        assert_eq!(result.status, raw_return(Status::BAD_STATE));
        assert_eq!(
            instrumentation::take_events(),
            [
                Event::DoSyscall { syscall_num: ZX_SYS_PROCESS_EXIT, pc: PC },
                Event::ValidSyscallPC("process_exit"),
                // The return code is an `i64`, so all 64 bits are preserved.
                Event::SysCall { name: "process_exit", args: vec![HIGH_GARBAGE | 7] },
            ]
        );
    }

    #[test]
    fn wrapper_copies_out_handles_after_a_successful_syscall() {
        reset();
        // SAFETY: The stubbed `do_syscall` has no execution context requirements.
        let result = unsafe { wrapper_channel_create(HIGH_GARBAGE | 1, OUT0_ADDR, OUT1_ADDR, PC) };
        assert_eq!(result.status, raw_return_ok());
        assert_eq!(
            instrumentation::take_events(),
            [
                Event::DoSyscall { syscall_num: ZX_SYS_CHANNEL_CREATE, pc: PC },
                Event::ValidSyscallPC("channel_create"),
                // The output handles are initialized to `ZX_HANDLE_INVALID` before the call.
                Event::SysCall {
                    name: "channel_create",
                    args: vec![1, ZX_HANDLE_INVALID.into(), ZX_HANDLE_INVALID.into()],
                },
                // The created handles are copied out, in parameter order.
                Event::CopyToUser { addr: OUT0_ADDR as usize, value: CREATED_HANDLES[0].into() },
                Event::CopyToUser { addr: OUT1_ADDR as usize, value: CREATED_HANDLES[1].into() },
            ]
        );
    }

    #[test]
    fn wrapper_skips_handle_copy_out_after_a_failed_syscall() {
        reset();
        SYS_STATUS.set(Err(Status::NO_MEMORY));
        // SAFETY: The stubbed `do_syscall` has no execution context requirements.
        let result = unsafe { wrapper_channel_create(0, OUT0_ADDR, OUT1_ADDR, PC) };
        assert_eq!(result.status, raw_return(Status::NO_MEMORY));
        let events = instrumentation::take_events();
        assert_eq!(events.len(), 3, "{events:?}");
        assert!(matches!(events[2], Event::SysCall { name: "channel_create", .. }), "{events:?}");
    }

    #[test]
    fn wrapper_signals_a_handle_leak_for_each_failed_handle_copy_out() {
        reset();
        instrumentation::fault_user_addr(OUT0_ADDR as usize);
        instrumentation::fault_user_addr(OUT1_ADDR as usize);
        // SAFETY: The stubbed `do_syscall` has no execution context requirements.
        let result = unsafe { wrapper_channel_create(0, OUT0_ADDR, OUT1_ADDR, PC) };
        // The status of the last copy-out is returned.
        assert_eq!(result.status, raw_return(Status::INVALID_ARGS));
        let events = instrumentation::take_events();
        assert_eq!(
            events[3..],
            [
                // Every failed copy-out is signaled, and the remaining handles are still
                // copied out.
                Event::CopyToUser { addr: OUT0_ADDR as usize, value: CREATED_HANDLES[0].into() },
                Event::SignalPolicyException { code: ZX_EXCP_POLICY_CODE_HANDLE_LEAK, data: 0 },
                Event::CopyToUser { addr: OUT1_ADDR as usize, value: CREATED_HANDLES[1].into() },
                Event::SignalPolicyException { code: ZX_EXCP_POLICY_CODE_HANDLE_LEAK, data: 0 },
            ]
        );
    }

    #[test]
    fn wrapper_returns_the_status_of_the_last_handle_copy_out() {
        reset();
        instrumentation::fault_user_addr(OUT0_ADDR as usize);
        // SAFETY: The stubbed `do_syscall` has no execution context requirements.
        let result = unsafe { wrapper_channel_create(0, OUT0_ADDR, OUT1_ADDR, PC) };
        // The generated wrapper copies out each handle in turn, so a failed copy-out of an
        // earlier handle is signaled but not reported through the return value if a later
        // copy-out succeeds.
        assert_eq!(result.status, raw_return_ok());
        let events = instrumentation::take_events();
        assert_eq!(
            events[3..],
            [
                Event::CopyToUser { addr: OUT0_ADDR as usize, value: CREATED_HANDLES[0].into() },
                Event::SignalPolicyException { code: ZX_EXCP_POLICY_CODE_HANDLE_LEAK, data: 0 },
                Event::CopyToUser { addr: OUT1_ADDR as usize, value: CREATED_HANDLES[1].into() },
            ]
        );
    }
}
